const KOLKATA_BY_SLUG = new Map(KOLKATA_REGISTRY_PROJECTS.map((p) => [p.slug.toLowerCase(), p]));
const KOLKATA_BY_ID = new Map(KOLKATA_REGISTRY_PROJECTS.map((p) => [String(p.id), p]));

function buildAmenitiesForKolkata(features = []) {
  const defaultList = ["24x7 Security", "Landscaped Garden", "Clubhouse", "Car Parking", "Power Backup", "Gym"];
  const list = features && features.length > 0 ? features : defaultList;
  return list.map((name) => ({
    name,
    category: "Lifestyle",
    icon: "Sparkles",
  }));
}

function buildConfigurationsForKolkataProject(p) {
  const plans = [];
  const rawTypes = (p.flatTypes || p.configuration || p.type || "Apartment")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);

  const areaNums = String(p.carpetArea || p.builtUpArea || "")
    .replace(/,/g, "")
    .match(/\d+(?:\.\d+)?/g)
    ?.map(Number)
    .filter((n) => n >= 150 && n <= 50000) || [];

  const minArea = areaNums.length > 0 ? Math.min(...areaNums) : null;
  const maxArea = areaNums.length > 0 ? Math.max(...areaNums) : null;

  rawTypes.forEach((bhkName, idx) => {
    let areaVal = p.carpetArea || "On Request";
    if (minArea !== null && maxArea !== null) {
      if (rawTypes.length === 1) {
        areaVal = `${minArea} - ${maxArea} sq.ft`;
      } else {
        const ratio = idx / (rawTypes.length - 1);
        const est = Math.round(minArea + ratio * (maxArea - minArea));
        areaVal = `${est} sq.ft`;
      }
    }
    const imgUrl = p.images?.[0] || "/images/placeholder-property.jpg";
    plans.push({
      type: bhkName,
      bhk: bhkName,
      carpetArea: areaVal,
      superArea: p.builtUpArea ? `${p.builtUpArea} sq.ft` : areaVal,
      area: areaVal,
      price: p.price && p.price !== "On Request" ? `₹ ${p.price.replace(/^₹\s*/, '')}` : "On Request",
      specs: {
        bedrooms: parseInt(bhkName, 10) || 2,
        bathrooms: parseInt(bhkName, 10) || 2,
        balconies: 1,
        parking: "Covered Parking",
      },
      facing: "East / North Facing",
      description: `Verified configuration at ${p.name}, ${p.location}.`,
      propertyType: p.type || "Apartment",
      image: imgUrl,
      layoutImage: imgUrl,
      key: `${p.id}-cfg-${idx}`,
    });
  });

  return plans;
}

export function getKolkataProjectBySlug(rawSlug) {
  if (!rawSlug) return null;
  const clean = decodeURIComponent(String(rawSlug)).toLowerCase().trim();
  let p = KOLKATA_BY_SLUG.get(clean) || KOLKATA_BY_ID.get(clean);
  if (!p) {
    const pidMatch = clean.match(/-pid-(\d+)$/) || clean.match(/-(\d+)$/);
    if (pidMatch) p = KOLKATA_BY_ID.get(pidMatch[1]);
  }
  if (!p) {
    p = KOLKATA_REGISTRY_PROJECTS.find(
      (item) =>
        item.slug.toLowerCase() === clean ||
        String(item.id) === clean ||
        item.name.toLowerCase().replace(/[^a-z0-9]+/g, "-") === clean
    );
  }
  if (!p) return null;

  const specs = [
    { label: "Configurations", value: p.flatTypes || "On Request" },
    { label: "Carpet Area", value: p.carpetArea ? `${p.carpetArea} sq.ft` : "On Request" },
    { label: "Built-up Area", value: p.builtUpArea ? `${p.builtUpArea} sq.ft` : "On Request" },
    { label: "Possession", value: p.possession || "Under Construction" },
    { label: "Project Status", value: p.status || "Under Construction" },
    { label: "Project Area", value: p.projectArea || "On Request" },
    { label: "Average Rate", value: p.avgPrice ? (p.avgPrice.includes('₹') ? p.avgPrice : `₹${p.avgPrice} / sq.ft`) : "On Request" },
    { label: "West Bengal RERA ID", value: p.rera || "Not Available" },
  ];

  const reraIds = (p.rera_informations && p.rera_informations.length > 0)
    ? p.rera_informations
    : (p.rera && p.rera !== "Not Available"
        ? p.rera.split(",").map((id) => ({ rera_id: id.trim() }))
        : []);

  const sameLocality = KOLKATA_REGISTRY_PROJECTS.filter((item) => item.locality === p.locality && item.slug !== p.slug);
  const otherKolkata = (sameLocality.length >= 3
    ? sameLocality
    : KOLKATA_REGISTRY_PROJECTS.filter((item) => item.slug !== p.slug)
  ).slice(0, 4);

  const landmarks = [
    { name: `${p.locality} Metro / Railway Station`, distance: "1.2 km", time: "5 mins", type: "Transit" },
    { name: "EM Bypass / Major Arterial Road", distance: "2.5 km", time: "8 mins", type: "Road" },
    { name: "Apollo Multispeciality / AMRI Hospital", distance: "3.0 km", time: "10 mins", type: "Healthcare" },
    { name: "Leading CBSE / ICSE School & College", distance: "1.8 km", time: "6 mins", type: "Education" },
    { name: "Sector V / New Town IT Tech Hub", distance: "4.8 km", time: "12 mins", type: "Work" },
  ];

  return {
    id: p.id,
    slug: p.slug,
    title: p.name,
    name: p.name,
    builder: p.builder,
    builderLogo: p.builderLogo || "/images/logo/logo-emblem.png",
    developerSlug: p.developerSlug || String(p.builder || "").toLowerCase().replace(/[^a-z0-9]+/g, "-"),
    city: "kolkata",
    cityName: "Kolkata",
    region: p.region || "Kolkata",
    locality: p.locality,
    location: p.location,
    fullAddress: p.fullAddress || `${p.name}, ${p.locality}, Kolkata, West Bengal`,
    lat: p.lat,
    lng: p.lng,
    price: p.price && p.price.includes('₹') ? p.price : `₹ ${p.price}`,
    priceRange: p.priceRange || p.price,
    priceNumeric: p.priceNumeric,
    avgPrice: p.avgPrice,
    flatTypes: p.flatTypes,
    carpetArea: p.carpetArea,
    builtUpArea: p.builtUpArea,
    projectArea: p.projectArea,
    possession: p.possession,
    status: p.status,
    rera: p.rera,
    rera_informations: reraIds,
    stateReraLink: "https://rera.wb.gov.in/",
    tag: p.tag || "Verified",
    type: p.type || "Apartment",
    isExclusive: p.isExclusive || false,
    isRera: p.isRera !== undefined ? p.isRera : true,
    rating: p.rating || 4.8,
    reviewsCount: 96,
    images: p.images && p.images.length > 0 ? p.images : ["/images/placeholder-property.jpg"],
    overview: p.description || `${p.name} is a premier residential community developed by ${p.builder} in ${p.location}, offering thoughtfully planned residences with modern amenities.`,
    highlights: [
      `Prime address in ${p.location}`,
      `Developed by ${p.builder}`,
      p.rera && p.rera !== "Not Available" ? `West Bengal RERA Registered: ${p.rera}` : "Verified PropertyPistol Kolkata Listing",
      `Available Configurations: ${p.flatTypes || p.type}`,
      `Possession: ${p.possession || "Under Construction"}`,
    ],
    specs,
    amenities: buildAmenitiesForKolkata(p.features),
    amenitiesDetails: [],
    floorPlans: buildConfigurationsForKolkataProject(p),
    bankOffers: [],
    landmarks,
    developerInfo: {
      name: p.builder,
      slug: p.developerSlug || String(p.builder || "").toLowerCase().replace(/[^a-z0-9]+/g, "-"),
      logo: p.builderLogo || "/images/logo/logo-emblem.png",
      experience: "20+ Years",
      projectsCount: "30+ Projects",
      established: "2005",
      description: p.builderDescription || `${p.builder} is a prominent developer with verified high-grade residential developments in Kolkata.`,
    },
    relatedProjectSlugs: otherKolkata.map((o) => o.slug),
    nearbyProjects: otherKolkata.map((o) => ({
      id: o.id,
      slug: o.slug,
      name: o.name,
      title: o.name,
      location: o.location,
      price: o.price,
      flatTypes: o.flatTypes,
      images: o.images,
      city: "kolkata",
    })),
    referenceUrl: p.referenceUrl || `https://www.propertypistol.com/projects/${p.slug}`,
  };
}

export const KOLKATA_ALL_SLUGS = KOLKATA_REGISTRY_PROJECTS.map((p) => p.slug);

export const KOLKATA_PROJECT_COORDINATES = Object.fromEntries(
  KOLKATA_REGISTRY_PROJECTS.map((p) => [
    p.slug,
    {
      lat: p.lat,
      lng: p.lng,
      locality: p.locality,
      city: "kolkata",
      cityName: "Kolkata",
      propertyType: p.type || "Apartment",
      verified: true,
    },
  ])
);
